    /** Every fighter's frames: the picture, left, top, width, height, across to her feet and down to the ground of each. */
    static final short[][][] FRAMES = new short[DATA.length][COUNT][7];

    static {
        for (int fighter = 0; fighter < DATA.length; fighter++) {
            String[] numbers = DATA[fighter].split(" ");
            for (int index = 0; index < numbers.length; index++) FRAMES[fighter][index / 7][index % 7] = Short.parseShort(numbers[index]);
        }
    }

